mapper.select:
select employee_id,employee_name,post from hrm_employee where is_del = 0 and entry_status in (1,3)


        and dept_id is null


        and dept_id = #{deptId}

sql.if:
and coalesce(a.age,
if(a.date_of_birth is not null, timestampdiff(year, a.date_of_birth, curdate()), null),
if(a.id_type = 1 and a.id_number regexp '^[0-9]{17}[0-9Xx]$', timestampdiff(year, str_to_date(substring(a.id_number, 7, 8), '%Y%m%d'), curdate()), null))
>= #{data.ageMin}

and coalesce(a.age,
if(a.date_of_birth is not null, timestampdiff(year, a.date_of_birth, curdate()), null),
if(a.id_type = 1 and a.id_number regexp '^[0-9]{17}[0-9Xx]$', timestampdiff(year, str_to_date(substring(a.id_number, 7, 8), '%Y%m%d'), curdate()), null))
<= #{data.ageMax}

and (
month(a.date_of_birth) = #{data.birthMonth}
or (a.birthday is not null and a.birthday != '' and cast(substring(replace(a.birthday, '-', ''), 1, 2) as unsigned) = #{data.birthMonth})
or (a.id_type = 1 and a.id_number regexp '^[0-9]{17}[0-9Xx]$' and cast(substring(a.id_number, 11, 2) as unsigned) = #{data.birthMonth})
)

mapper.select:
select a.employee_id
from hrm_employee a
where a.is_del = 0
and (

    date_format(a.date_of_birth, '%m%d') = #{solar}


    or

        a.birthday = #{lunar}


)
group by a.employee_id
